// One component owns __html; the transform is presentational, applied after.
import DOMPurify from 'dompurify'

export const SafeHtml = ({html, transform, ...rest}: Props) => {
  const clean = DOMPurify.sanitize(html ?? '')
  return <div {...rest} dangerouslySetInnerHTML={{__html: transform ? transform(clean) : clean}} />
}
